 "Ανατραφείς δε υπό της εθνικής μητρός αυτού Θεοδοσίας μετά τον θάνατον του "
 "χριστιανού πατρός αυτού, έλαβεν αρίστην παιδείαν, ανήλθε ταχέως εν τη "
