 "τα τραύματα αυτών και στηρίζων τας ψυχάς αυτών. Άπαξ διήλθεν όλην την "
 "νύκτα εν τη φυλακή μεθ' επτά ασκητών διδασκάλων των χριστιανών, οίτινες "
